import json, sys
out = []
for text in json.load(sys.stdin):
    try:
        json.loads(text)
        out.append(None)
    except json.JSONDecodeError as exc:
        out.append(str(exc))
    except Exception as exc:
        out.append("OTHER " + type(exc).__name__)
print(json.dumps(out))
